def solve(s):
    depth = 0
    for c in s:
        if c == '(':
            depth += 1
        elif c == ')':
            depth -= 1
            if depth < 0:
                return 0
    return 1 if depth == 0 else 0

def solve(s):
    stack = []
    for tok in s.split():
        if tok == '+':
            b = stack.pop(); a = stack.pop(); stack.append(a + b)
        elif tok == '-':
            b = stack.pop(); a = stack.pop(); stack.append(a - b)
        elif tok == '*':
            b = stack.pop(); a = stack.pop(); stack.append(a * b)
        else:
            stack.append(int(tok))
    return stack[-1] if stack else 0

def solve(s):
    xs = [int(t) for t in s.split()]
    if not xs:
        return 0
    best = cur = 1
    for i in range(1, len(xs)):
        if xs[i] > xs[i - 1]:
            cur += 1
        else:
            cur = 1
        best = max(best, cur)
    return best

