def solve(s, n):
    xs = [int(t) for t in s.split()]
    A = [xs[i * n:(i + 1) * n] for i in range(n)]
    total = 0
    for i in range(n):
        for k in range(n):
            total += A[i][k] * A[k][i]
    return total

def solve(s):
    if not s:
        return 0
    runs = 1
    for i in range(1, len(s)):
        if s[i] != s[i - 1]:
            runs += 1
    return runs

def solve(coins, amount):
    cs = [int(t) for t in coins.split()]
    INF = float('inf')
    dp = [0] + [INF] * amount
    for a in range(1, amount + 1):
        for c in cs:
            if c <= a and dp[a - c] + 1 < dp[a]:
                dp[a] = dp[a - c] + 1
    return -1 if dp[amount] == INF else dp[amount]
